-- Communications C2-A (docs/communications-c2.md §3.1): connected mailboxes, encrypted provider
-- credentials, pending OAuth authorizations and durable sync jobs. Generated by `prisma migrate diff`,
-- then the constraints, guards, grants and RLS Prisma cannot express were added by hand (sections
-- marked "hand-written"). Wrapped in one transaction (docs/migration-readiness.md §7, STAB-M6).
--
-- Ordering: depends only on 20261113150000_tenancy (businesses, audit_events). It references no C1,
-- finance, people or scheduling object and changes no existing row. No privileged SQL is needed.
-- No mail content is stored by anything in this migration.
BEGIN;
-- CreateTable
CREATE TABLE "mail_connections" (
    "id" UUID NOT NULL,
    "business_id" UUID NOT NULL,
    "provider" TEXT NOT NULL,
    "owner_user_id" UUID NOT NULL,
    "provider_account_id" TEXT NOT NULL,
    "mailbox_address" TEXT NOT NULL,
    "display_name" TEXT,
    "status" TEXT NOT NULL DEFAULT 'ACTIVE',
    "sharing" TEXT NOT NULL DEFAULT 'OWNER_ONLY',
    "granted_scopes" TEXT[],
    "sync_enabled" BOOLEAN NOT NULL DEFAULT true,
    "sync_cursor" TEXT,
    "last_synced_at" TIMESTAMPTZ,
    "last_error_code" TEXT,
    "connected_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "status_changed_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "disconnected_at" TIMESTAMPTZ,
    "disconnected_by_id" UUID,
    "version" INTEGER NOT NULL DEFAULT 1,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "mail_connections_pkey" PRIMARY KEY ("business_id","id")
);

-- CreateTable
CREATE TABLE "mail_connection_credentials" (
    "business_id" UUID NOT NULL,
    "connection_id" UUID NOT NULL,
    "key_id" TEXT NOT NULL,
    "credential_version" UUID NOT NULL,
    "refresh_token_enc" TEXT NOT NULL,
    "access_token_enc" TEXT,
    "access_token_expires_at" TIMESTAMPTZ,
    "refresh_lease_id" UUID,
    "refresh_lease_until" TIMESTAMPTZ,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "mail_connection_credentials_pkey" PRIMARY KEY ("business_id","connection_id")
);

-- CreateTable
CREATE TABLE "mail_oauth_states" (
    "id" UUID NOT NULL,
    "business_id" UUID NOT NULL,
    "state_hash" CHAR(64) NOT NULL,
    "user_id" UUID NOT NULL,
    "provider" TEXT NOT NULL,
    "connection_id" UUID,
    "code_verifier_enc" TEXT NOT NULL,
    "expires_at" TIMESTAMPTZ NOT NULL,
    "consumed_at" TIMESTAMPTZ,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "mail_oauth_states_pkey" PRIMARY KEY ("business_id","id")
);

-- CreateTable
CREATE TABLE "mail_sync_jobs" (
    "id" UUID NOT NULL,
    "business_id" UUID NOT NULL,
    "connection_id" UUID NOT NULL,
    "kind" TEXT NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'QUEUED',
    "requested_by_id" UUID,
    "attempts" SMALLINT NOT NULL DEFAULT 0,
    "max_attempts" SMALLINT NOT NULL DEFAULT 5,
    "run_after" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "lease_id" UUID,
    "lease_expires_at" TIMESTAMPTZ,
    "started_at" TIMESTAMPTZ,
    "finished_at" TIMESTAMPTZ,
    "last_error_code" TEXT,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "mail_sync_jobs_pkey" PRIMARY KEY ("business_id","id")
);

-- CreateIndex
CREATE INDEX "mail_connections_business_id_owner_user_id_created_at_idx" ON "mail_connections"("business_id", "owner_user_id", "created_at" DESC);

-- CreateIndex
CREATE UNIQUE INDEX "mail_oauth_states_state_hash_key" ON "mail_oauth_states"("state_hash");

-- CreateIndex
CREATE INDEX "mail_oauth_states_business_id_user_id_expires_at_idx" ON "mail_oauth_states"("business_id", "user_id", "expires_at");

-- CreateIndex
CREATE INDEX "mail_sync_jobs_business_id_status_run_after_idx" ON "mail_sync_jobs"("business_id", "status", "run_after");

-- CreateIndex
CREATE INDEX "mail_sync_jobs_business_id_connection_id_created_at_idx" ON "mail_sync_jobs"("business_id", "connection_id", "created_at" DESC);

-- AddForeignKey
ALTER TABLE "mail_connections" ADD CONSTRAINT "mail_connections_business_fkey" FOREIGN KEY ("business_id") REFERENCES "businesses"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "mail_connection_credentials" ADD CONSTRAINT "mail_connection_credentials_business_fkey" FOREIGN KEY ("business_id") REFERENCES "businesses"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "mail_connection_credentials" ADD CONSTRAINT "mail_connection_credentials_connection_fkey" FOREIGN KEY ("business_id", "connection_id") REFERENCES "mail_connections"("business_id", "id") ON DELETE CASCADE ON UPDATE NO ACTION;

-- AddForeignKey
ALTER TABLE "mail_oauth_states" ADD CONSTRAINT "mail_oauth_states_business_fkey" FOREIGN KEY ("business_id") REFERENCES "businesses"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "mail_oauth_states" ADD CONSTRAINT "mail_oauth_states_connection_fkey" FOREIGN KEY ("business_id", "connection_id") REFERENCES "mail_connections"("business_id", "id") ON DELETE NO ACTION ON UPDATE NO ACTION;

-- AddForeignKey
ALTER TABLE "mail_sync_jobs" ADD CONSTRAINT "mail_sync_jobs_business_fkey" FOREIGN KEY ("business_id") REFERENCES "businesses"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "mail_sync_jobs" ADD CONSTRAINT "mail_sync_jobs_connection_fkey" FOREIGN KEY ("business_id", "connection_id") REFERENCES "mail_connections"("business_id", "id") ON DELETE NO ACTION ON UPDATE NO ACTION;



-- =============================================================================================
-- Hand-written: constraints, guards, grants and RLS.
-- SQLSTATE class CM (communications), continued from C1: CM005 connection identity is fixed,
-- CM006 a disconnected connection is final, CM007 invalid sync job transition.
-- =============================================================================================

-- ---- mail_connections ------------------------------------------------------------------------
ALTER TABLE "mail_connections"
  ADD CONSTRAINT mail_connections_provider_values CHECK ("provider" IN ('GOOGLE', 'MICROSOFT')),
  ADD CONSTRAINT mail_connections_status_values CHECK ("status" IN ('ACTIVE', 'NEEDS_REAUTH', 'DISCONNECTED')),
  ADD CONSTRAINT mail_connections_sharing_values CHECK ("sharing" IN ('OWNER_ONLY', 'BUSINESS')),
  ADD CONSTRAINT mail_connections_account_length CHECK (char_length("provider_account_id") BETWEEN 1 AND 255),
  ADD CONSTRAINT mail_connections_address_format CHECK (
    char_length("mailbox_address") BETWEEN 3 AND 320 AND "mailbox_address" = lower("mailbox_address") AND position('@' in "mailbox_address") > 1),
  ADD CONSTRAINT mail_connections_display_name_length CHECK ("display_name" IS NULL OR char_length("display_name") BETWEEN 1 AND 200),
  ADD CONSTRAINT mail_connections_scopes_present CHECK ("granted_scopes" IS NOT NULL AND cardinality("granted_scopes") BETWEEN 1 AND 50),
  ADD CONSTRAINT mail_connections_cursor_length CHECK ("sync_cursor" IS NULL OR char_length("sync_cursor") <= 4096),
  -- A stable code, never provider text.
  ADD CONSTRAINT mail_connections_error_code_format CHECK ("last_error_code" IS NULL OR "last_error_code" ~ '^[a-z][a-z_]{1,48}$'),
  ADD CONSTRAINT mail_connections_disconnected_pair CHECK (("status" = 'DISCONNECTED') = ("disconnected_at" IS NOT NULL)),
  ADD CONSTRAINT mail_connections_version_positive CHECK ("version" >= 1);
-- One live connection per mailbox per business. The same mailbox may be connected in another business.
CREATE UNIQUE INDEX "mail_connections_live_account_key" ON "mail_connections" ("business_id", "provider", "provider_account_id")
  WHERE "status" <> 'DISCONNECTED';

CREATE FUNCTION mail_connections_guard_update() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  IF (NEW.id, NEW.business_id, NEW.provider, NEW.provider_account_id, NEW.owner_user_id, NEW.created_at)
     IS DISTINCT FROM (OLD.id, OLD.business_id, OLD.provider, OLD.provider_account_id, OLD.owner_user_id, OLD.created_at) THEN
    RAISE EXCEPTION 'connection identity is fixed' USING ERRCODE = 'CM005';
  END IF;
  IF OLD.status = 'DISCONNECTED' THEN
    RAISE EXCEPTION 'disconnected connections are final' USING ERRCODE = 'CM006';
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    NEW.status_changed_at := now();
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER mail_connections_guard_update BEFORE UPDATE ON "mail_connections" FOR EACH ROW EXECUTE FUNCTION mail_connections_guard_update();

-- Tokens never outlive an active grant: leaving ACTIVE (reauth needed, disconnected) deletes them in
-- the same statement, whatever the service code does.
CREATE FUNCTION mail_connections_drop_credentials() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  IF NEW.status <> 'ACTIVE' AND OLD.status = 'ACTIVE' THEN
    DELETE FROM "mail_connection_credentials" WHERE "business_id" = NEW.business_id AND "connection_id" = NEW.id;
  END IF;
  RETURN NULL;
END $$;
CREATE TRIGGER mail_connections_drop_credentials AFTER UPDATE OF "status" ON "mail_connections" FOR EACH ROW EXECUTE FUNCTION mail_connections_drop_credentials();

-- ---- mail_connection_credentials -------------------------------------------------------------
-- Envelope format v1.<keyId>.<iv>.<ciphertext+tag> (base64url): plaintext cannot be stored by mistake.
ALTER TABLE "mail_connection_credentials"
  ADD CONSTRAINT mail_connection_credentials_key_id_format CHECK ("key_id" ~ '^[a-z0-9][a-z0-9_-]{0,31}$'),
  ADD CONSTRAINT mail_connection_credentials_refresh_format CHECK ("refresh_token_enc" ~ '^v1\.[a-z0-9][a-z0-9_-]{0,31}\.[A-Za-z0-9_-]{16}\.[A-Za-z0-9_-]{22,}$'),
  ADD CONSTRAINT mail_connection_credentials_access_format CHECK (
    "access_token_enc" IS NULL OR "access_token_enc" ~ '^v1\.[a-z0-9][a-z0-9_-]{0,31}\.[A-Za-z0-9_-]{16}\.[A-Za-z0-9_-]{22,}$'),
  ADD CONSTRAINT mail_connection_credentials_access_pair CHECK (("access_token_enc" IS NULL) = ("access_token_expires_at" IS NULL)),
  ADD CONSTRAINT mail_connection_credentials_lease_pair CHECK (("refresh_lease_id" IS NULL) = ("refresh_lease_until" IS NULL));

-- Credentials can only be stored for an active connection.
CREATE FUNCTION mail_connection_credentials_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM "mail_connections" c
                 WHERE c."business_id" = NEW.business_id AND c."id" = NEW.connection_id AND c."status" = 'ACTIVE') THEN
    RAISE EXCEPTION 'credentials need an active connection' USING ERRCODE = 'CM006';
  END IF;
  IF TG_OP = 'UPDATE' AND (NEW.business_id, NEW.connection_id, NEW.created_at) IS DISTINCT FROM (OLD.business_id, OLD.connection_id, OLD.created_at) THEN
    RAISE EXCEPTION 'credential identity is fixed' USING ERRCODE = 'CM005';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER mail_connection_credentials_guard BEFORE INSERT OR UPDATE ON "mail_connection_credentials" FOR EACH ROW EXECUTE FUNCTION mail_connection_credentials_guard();

-- ---- mail_oauth_states -----------------------------------------------------------------------
ALTER TABLE "mail_oauth_states"
  ADD CONSTRAINT mail_oauth_states_provider_values CHECK ("provider" IN ('GOOGLE', 'MICROSOFT')),
  ADD CONSTRAINT mail_oauth_states_hash_format CHECK ("state_hash" ~ '^[0-9a-f]{64}$'),
  ADD CONSTRAINT mail_oauth_states_verifier_format CHECK ("code_verifier_enc" ~ '^v1\.[a-z0-9][a-z0-9_-]{0,31}\.[A-Za-z0-9_-]{16}\.[A-Za-z0-9_-]{22,}$'),
  ADD CONSTRAINT mail_oauth_states_short_lived CHECK ("expires_at" > "created_at" AND "expires_at" <= "created_at" + interval '15 minutes');

-- created_at is database time, so the lifetime CHECK cannot be widened by the client.
CREATE FUNCTION mail_oauth_states_stamp_insert() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  NEW.created_at := now();
  NEW.consumed_at := NULL;
  RETURN NEW;
END $$;
CREATE TRIGGER mail_oauth_states_stamp_insert BEFORE INSERT ON "mail_oauth_states" FOR EACH ROW EXECUTE FUNCTION mail_oauth_states_stamp_insert();

-- ---- mail_sync_jobs --------------------------------------------------------------------------
ALTER TABLE "mail_sync_jobs"
  ADD CONSTRAINT mail_sync_jobs_kind_values CHECK ("kind" IN ('INITIAL', 'INCREMENTAL', 'FULL_RESYNC')),
  ADD CONSTRAINT mail_sync_jobs_status_values CHECK ("status" IN ('QUEUED', 'RUNNING', 'SUCCEEDED', 'FAILED', 'CANCELLED')),
  ADD CONSTRAINT mail_sync_jobs_attempts_range CHECK ("attempts" >= 0 AND "max_attempts" BETWEEN 1 AND 20 AND "attempts" <= "max_attempts"),
  -- A running job always holds a lease; nothing else does.
  ADD CONSTRAINT mail_sync_jobs_lease_running CHECK ((("status" = 'RUNNING') = ("lease_id" IS NOT NULL)) AND (("lease_id" IS NULL) = ("lease_expires_at" IS NULL))),
  ADD CONSTRAINT mail_sync_jobs_finished_pair CHECK (("status" IN ('SUCCEEDED', 'FAILED', 'CANCELLED')) = ("finished_at" IS NOT NULL)),
  ADD CONSTRAINT mail_sync_jobs_error_code_format CHECK ("last_error_code" IS NULL OR "last_error_code" ~ '^[a-z][a-z_]{1,48}$');
-- Idempotent enqueue: at most one queued or running job per connection.
CREATE UNIQUE INDEX "mail_sync_jobs_active_key" ON "mail_sync_jobs" ("business_id", "connection_id") WHERE "status" IN ('QUEUED', 'RUNNING');

CREATE FUNCTION mail_sync_jobs_guard_update() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  IF (NEW.id, NEW.business_id, NEW.connection_id, NEW.kind, NEW.requested_by_id, NEW.max_attempts, NEW.created_at)
     IS DISTINCT FROM (OLD.id, OLD.business_id, OLD.connection_id, OLD.kind, OLD.requested_by_id, OLD.max_attempts, OLD.created_at) THEN
    RAISE EXCEPTION 'sync job identity is fixed' USING ERRCODE = 'CM005';
  END IF;
  IF OLD.status IN ('SUCCEEDED', 'FAILED', 'CANCELLED') THEN
    RAISE EXCEPTION 'finished sync jobs are final' USING ERRCODE = 'CM007';
  END IF;
  IF NOT ((OLD.status = 'QUEUED' AND NEW.status IN ('QUEUED', 'RUNNING', 'CANCELLED'))
       OR (OLD.status = 'RUNNING' AND NEW.status IN ('RUNNING', 'QUEUED', 'SUCCEEDED', 'FAILED', 'CANCELLED'))) THEN
    RAISE EXCEPTION 'invalid sync job transition' USING ERRCODE = 'CM007';
  END IF;
  IF NEW.attempts < OLD.attempts THEN
    RAISE EXCEPTION 'attempts only increase' USING ERRCODE = 'CM007';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER mail_sync_jobs_guard_update BEFORE UPDATE ON "mail_sync_jobs" FOR EACH ROW EXECUTE FUNCTION mail_sync_jobs_guard_update();

-- ---- least privilege ---------------------------------------------------------------------------
-- No DELETE on connections or jobs (they are the record of what was connected and run). Credentials
-- are deleted on revocation; expired authorizations are pruned.
REVOKE ALL ON "mail_connections", "mail_connection_credentials", "mail_oauth_states", "mail_sync_jobs" FROM bos_app;
GRANT SELECT, INSERT ON "mail_connections", "mail_oauth_states", "mail_sync_jobs" TO bos_app;
GRANT SELECT, INSERT, DELETE ON "mail_connection_credentials" TO bos_app;
GRANT DELETE ON "mail_oauth_states" TO bos_app;
GRANT UPDATE ("mailbox_address", "display_name", "status", "sharing", "granted_scopes", "sync_enabled", "sync_cursor", "last_synced_at",
              "last_error_code", "connected_at", "status_changed_at", "disconnected_at", "disconnected_by_id", "version", "updated_at")
  ON "mail_connections" TO bos_app;
GRANT UPDATE ("key_id", "credential_version", "refresh_token_enc", "access_token_enc", "access_token_expires_at", "refresh_lease_id", "refresh_lease_until", "updated_at")
  ON "mail_connection_credentials" TO bos_app;
GRANT UPDATE ("consumed_at") ON "mail_oauth_states" TO bos_app;
GRANT UPDATE ("status", "attempts", "run_after", "lease_id", "lease_expires_at", "started_at", "finished_at", "last_error_code", "updated_at")
  ON "mail_sync_jobs" TO bos_app;

-- ---- row-level security --------------------------------------------------------------------------
ALTER TABLE "mail_connections" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "mail_connections" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "mail_connections" FOR ALL TO bos_app
  USING      ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid)
  WITH CHECK ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid);
-- A mailbox is connected by the person who consented: the owner is the user of the unit of work.
CREATE POLICY owner_is_session_user ON "mail_connections" AS RESTRICTIVE FOR INSERT TO bos_app
  WITH CHECK ("owner_user_id" = nullif(current_setting('app.user_id', true), '')::uuid);

ALTER TABLE "mail_connection_credentials" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "mail_connection_credentials" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "mail_connection_credentials" FOR ALL TO bos_app
  USING      ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid)
  WITH CHECK ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid);

ALTER TABLE "mail_oauth_states" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "mail_oauth_states" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "mail_oauth_states" FOR ALL TO bos_app
  USING      ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid)
  WITH CHECK ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid);
CREATE POLICY started_by_session_user ON "mail_oauth_states" AS RESTRICTIVE FOR INSERT TO bos_app
  WITH CHECK ("user_id" = nullif(current_setting('app.user_id', true), '')::uuid);

ALTER TABLE "mail_sync_jobs" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "mail_sync_jobs" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "mail_sync_jobs" FOR ALL TO bos_app
  USING      ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid)
  WITH CHECK ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid);

-- ---- audit: system events with no acting user (docs/communications-c2.md §6) -------------------
-- The existing audit_tenant_write policy requires actor_user_id = the session user. A provider
-- revoking a grant, or a mailbox owner leaving, has no acting user; only these events may be written
-- without one, only for this business, and only when the unit of work has no session user.
CREATE POLICY audit_system_write ON "audit_events" FOR INSERT TO bos_app
  WITH CHECK ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid
              AND "actor_user_id" IS NULL
              AND nullif(current_setting('app.user_id', true), '') IS NULL
              AND "action" LIKE 'communications.system.%');

COMMIT;
